<?php require_once __DIR__ . '/../src/partials.php';$pdo=db();$from=$_GET['from']??date('Y-m-01');$to=$_GET['to']??date('Y-m-d');$s=$pdo->prepare("SELECT p.code,p.name,p.unit,p.current_stock,p.min_stock,COALESCE(SUM(CASE WHEN m.movement_type='IN' THEN m.quantity ELSE 0 END),0) qty_in,COALESCE(SUM(CASE WHEN m.movement_type='OUT' THEN m.quantity ELSE 0 END),0) qty_out FROM products p LEFT JOIN stock_movements m ON m.product_id=p.id AND m.created_at::date BETWEEN ? AND ? GROUP BY p.id ORDER BY p.name");$s->execute([$from,$to]);$rows=$s->fetchAll();page_start('รายงานสรุป');?><div class="card"><form class="actions"><label>จาก</label><input type="date" name="from" value="<?=h($from)?>"><label>ถึง</label><input type="date" name="to" value="<?=h($to)?>"><button class="primary">ดูรายงาน</button><a class="button success" href="/export.php?type=xlsx&from=<?=h($from)?>&to=<?=h($to)?>">Export Excel</a><a class="button danger" href="/export.php?type=pdf&from=<?=h($from)?>&to=<?=h($to)?>" target="_blank">Export PDF</a><?php if(is_admin()): ?><a class="button warning" href="/reset.php">คืนค่าโรงงาน</a><?php endif; ?></form></div><?php if(is_admin()): ?><div class="card" style="margin-top:16px"><div class="actions" style="justify-content:space-between;align-items:center"><div><strong>คืนค่าโรงงานข้อมูลคลัง</strong><div class="muted">ล้างประวัติรับเข้า/เบิกออก และรีเซ็ตยอดคงเหลือเป็น 0 โดยไม่ลบสินค้าและผู้ใช้งาน</div></div><a class="button warning" href="/reset.php">เปิดหน้าคืนค่าโรงงาน</a></div></div><?php endif; ?><div class="table-wrap"><table><tr><th>รหัส</th><th>สินค้า</th><th>หน่วย</th><th>คงเหลือ</th><th>เข้า</th><th>ออก</th><th>ขั้นต่ำ</th></tr><?php foreach($rows as $r):?><tr><td><?=h($r['code'])?></td><td><?=h($r['name'])?></td><td><?=h($r['unit'])?></td><td><?=number_format($r['current_stock'])?></td><td><?=number_format($r['qty_in'])?></td><td><?=number_format($r['qty_out'])?></td><td><?=number_format($r['min_stock'])?></td></tr><?php endforeach;?></table></div><?php page_end();
